head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.userId = "";        // 로그인 사용자 ID (onpageload 에서 세션으로 채움)
scwin.bzProcsNo = "";     // 업무처리번호 (onpageload 에서 파라미터로 채움)
scwin.conm = "";          // 회사명
scwin.seletedRow = "";    // 첨부파일 선택 ROW

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — searchDetail 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        scwin.userId = $c.session.getUserInfo("integUsrId");
        scwin.bzProcsNo = $c.data.getParameter("BZ_PROCS_NO");
        // 그리드 셀 HTML(onclick/href) 이 부르는 전역 함수 노출
        window.fn_FileDown = scwin.fileDown;
        window.fn_fileDel = scwin.fileDel;
        window.fn_changeFile = scwin.changeFile;
        scwin.searchDetail(); // 상세조회
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIL52810.onpageload" });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name upd_compUpload_oninputvaluechange
 * @description 첨부파일 선택 변경 — 선택 행에 파일명과 삭제확인 값을 세팅한다.
 * @param {String} fileName 파일명
 * @returns {void}
 * @hidden N
 */
scwin.upd_compUpload_oninputvaluechange = function (fileName) {
    try {
        const reName = fileName.match(/[^\\\/]+$/)[0];
        dlt_commitmentsRes2.setCellData(scwin.seletedRow, "cmitFileNm",  reName)

        if( dlt_commitmentsRes2.getCellData(scwin.seletedRow, "cmitFileNm") !== "") {
            dlt_commitmentsRes2.setCellData(scwin.seletedRow, "fileDelChk", "U");
        }
        //  else {
        //     $c.win.alert(scwin.seletedRow + " 행에 " + "선택된 파일이 없습니다");
        // }

        // grd_commitment.setCellDisabled(scwin.seletedRow, "fileDelChkView", true);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIL52810.upd_compUpload_oninputvaluechange" });
    }
};

/**
 * @method
 * @name btn_register_onclick
 * @description 「이행내역수정」 버튼 클릭 — 유효성 검사·확인 후 이행내역을 제출한다.
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_register_onclick = async function (e) {
    try {
        if (await scwin.validation()){
                if (! await $c.win.confirm("제출 후 수정이 불가능 합니다 제출하시겠습니까?")) {
                    return;
                }
            await scwin.register();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIL52810.btn_register_onclick" });
    }
};

/**
 * @method
 * @name grd_commitment_oncellclick
 * @description 그리드 셀 클릭 — 컬럼(파일명·확약서 등)에 따라 파일 다운로드 등 처리로 분기한다.
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {void}
 * @hidden N
 */
scwin.grd_commitment_oncellclick = function (rowIndex, columnIndex, columnId) {
    try {
        let bzProcsNo           = dlt_commitmentsRes2.getCellData(rowIndex, "bzProcsNo");
        let cmitContnSeq        = dlt_commitmentsRes2.getCellData(rowIndex, "cmitContnSeq");
        let cmitPerfmStatCd     = dlt_commitmentsRes2.getCellData(rowIndex, "cmitPerfmStatCd");
        let cmitFileNm          = dlt_commitmentsRes2.getCellData(rowIndex, "cmitFileNm");

        switch(columnId) {

            case "cmitFileNm" : // 파일 다운로드

                const param = {
                    cmitBzProcsNo : bzProcsNo
                    ,seq : cmitContnSeq
                    ,cmitTpCd : cmitPerfmStatCd
                    ,cmitAttachFileNm : cmitFileNm
                };

                const url = "/api/listing/listinvstg/commitments/file-download";

                $c.data.downFile(url, cmitFileNm, param);

                break;

        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIL52810.grd_commitment_oncellclick" });
    }
};

/**
 * @method
 * @name btn_moveList_onclick
 * @description 「목록」 버튼 클릭 — 목록 화면으로 이동한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_moveList_onclick = function (e) {
    try {
        scwin.goList()
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIL52810.btn_moveList_onclick" });
    }
};

/**
 * @method
 * @name dlt_commitmentsRes2_oncelldatachange
 * @description 업로드 후 셀 데이터 변경 — 첨부파일명을 세팅한다.
 * @param {Object} info 이벤트 정보 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dlt_commitmentsRes2_oncelldatachange = async function (info) {

// grd_commitment.setCellData
// dlt_commitmentsRes2.setCellData(info.realRowIndex, "comFileNm", dlt_commitmentsRes2.getCellData(info.realRowIndex, "fileName"));

};

///////// 4. 서브미션 콜백 영역 /////////
// submission

/**
 * @method
 * @name searchDetail
 * @description 확약사항 단건·이행내역 목록(상세)을 조회한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchDetail = async function () {

    dma_searchReq.setJSON({
        "userId" : scwin.userId,
        "bzProcsNo" : scwin.bzProcsNo
    });

    const sbmOptions = {
        id: "sbm_commitmentsDetail",
        action: "/api/listing/listinvstg/commitments/select-detail",
        method: "get",
        ref: "dma_searchReq",
        target: "dma_commitmentsRes1=body, dlt_commitmentsRes2=body.comCommitmentsListResponseDto",
        gridview: "grdMain"
    };

    const res = await $c.sbm.executeDynamic(sbmOptions);
    if(res.responseJSON.success) {
        let dataList =  res.responseJSON.body.comCommitmentsListResponseDto;
        dlt_commitmentsRes2.setBroadcast(false);
        for(let i = 0; i < dataList.length; i++) {
        const cmitFileNm = dataList[i].cmitFileNm;
        let innerHtml = "-";
        if(cmitFileNm && cmitFileNm !== "") {
            innerHtml = `
                <div id="attachFileList" title="${cmitFileNm}">
                  <a href="javascript:fn_FileDown('${dataList[i].bzProcsNo}' , '${dataList[i].cmitContnSeq}','20','${cmitFileNm}');">
                    <img src="/cm/images/dis/attach_5.gif" border="0"/> 다운로드
                  </a> 
                </div>
             `.trim();
            await dlt_commitmentsRes2.setCellData(i, "customFileNm", innerHtml);
        }
        }
        dlt_commitmentsRes2.setBroadcast(true, true);

    }
};

/**
 * @method
 * @name sbm_insertCommitments_submitdone
 * @description 저장 통신 응답 후처리 — 결과 메시지 표시 후 상세를 재조회한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.sbm_insertCommitments_submitdone = function (e) {

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name goList
 * @description 목록으로 이동
 * @returns {void}
 * @hidden N
 */
scwin.goList = function () {
    $c.win.moveUrl("/ui/lst/lstinvstg/ULDFIL52800.xml", scwin.conm );
};

/**
 * @method
 * @name register
 * @description 확약 이행내역을 저장(제출)한다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.register = async function() {

    await udcSaver.save({
        dataList: dlt_commitmentsRes2,
        dataListId: "commitmentsUploadFileReqeustDto",
        saveUrl:  "/api/listing/listinvstg/commitments/insert",
        onSuccess: function (res) {
            $c.win.alert("처리 성공했습니다.");
        },

        // onAfterSave: scwin.fn_list_sync //재조회
    });

}

/**
 * @method
 * @name customChageCmitPerfmYn
 * @description 이행여부 코드(N/그 외)를 이행중/완료 문자열로 바꾸는 커스텀 포매터.
 * @param {*} data 셀 값(원본 데이터)
 * @returns {String} 표시 문자열
 * @hidden N
 */
scwin.customChageCmitPerfmYn =  function (data) {

    return data === 'N' ? '이행중' : '완료'

}

/**
 * @method
 * @name fileDel
 * @description 첨부파일을 삭제한다.
 * @param {String} attachFileNm 명칭
 * @param {Number} rowIndex 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fileDel = async function( attachFileNm, rowIndex ) {

    const msg = attachFileNm + " 첨부파일을 삭제하시겠습니까?\n삭제된 파일은 복구가 불가능합니다.";

    if (!await $c.win.confirm(msg)) {
        return;
    }

    dlt_commitmentsRes2.setCellData(rowIndex, "comFileNm", "");
    // 파일삭제
    udcSaver.detachFile(rowIndex, dlt_commitmentsRes2);

}

/**
 * @method
 * @name changeFile
 * @description 파일 업로드 — 선택 행의 파일을 업로드한다.
 * @param {Number} index 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.changeFile = async function(index){
    // 파일선택일때
    scwin.attachFile(index);
}

/**
 * @method
 * @name attachFile
 * @description 선택한 행에 첨부파일을 연결한다(udcSaver 위임).
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.attachFile = function(row) {
    udcSaver.attachFile(row, dlt_commitmentsRes2);
};

/**
 * @method
 * @name validation
 * @description 유효성 검사 — 첨부파일 용량·필수값을 확인한다.
 * @returns {Promise<Boolean>} 검증 통과 여부
 * @hidden N
 */
scwin.validation = async function(){
        let listCnt=0; /*수정가능 상태체크*/

        for(let i = 0; i <= dlt_commitmentsRes2.getRowCount()-1; i++){

            let cmitPerfmStatCd  = dlt_commitmentsRes2.getCellData(i, "cmitPerfmStatCd");
            let comFileNm       = dlt_commitmentsRes2.getCellData(i, "comFileNm");

            let perfmOpinContn   = dlt_commitmentsRes2.getCellData(i, "perfmOpinContn");
            let fileDelChk       = dlt_commitmentsRes2.getCellData(i, "fileDelChk");
            let fileSize         = dlt_commitmentsRes2.getCellData(i, "fileSize");

            if(cmitPerfmStatCd === "20"|| cmitPerfmStatCd === "") {
                listCnt++
                if( ( comFileNm === "") || fileDelChk === "D") {
                    await $c.win.alert(( i + 1 ) + "번의 이행증빙자료를 첨부해 주세요");
                    return false;
                } else {
                        if( comFileNm !== ""){
                            if( fileSize > 20971520 ){
                            await $c.win.alert('첨부파일의 용량은 개당 20MB를 넘을수 없습니다.');
                                return false;
                            }

                        if( scwin.fileTypeChk(comFileNm) > 0 ) {
                            $c.win.alert(i+'번의 첨부할 수 없는 확장자를 가지 파일이 있습니다.\n사용가능 확장자 : DRT, bmp, gif, jpeg, jpg, png, hwp, docx, doc, xls, xlsx, ppt, pptx, pdf, zip, txt');
                            return false;
                        }
                }

            }
                if(perfmOpinContn === ""){
                    await $c.win.alert((i+1)+1 + "번의 의견을 작성해 주세요");
                    return false;
                }
            }

        }
        if(listCnt === 0){
            await $c.win.alert("수정가능한 상태가 없습니다.");
            return false;
        }

        return true;
    }

/**
 * @method
 * @name checkByte
 * @description 내용 바이트 수를 계산해 표시하고 2000byte 초과분은 잘라낸다.
 * @param {Object} _obj 대상 입력 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.checkByte = function (_obj) {
    // 기준바이트 수
    const standardByte = 2000;		// 2000B 제한
    const contnByte = scwin.getByte(_obj);

    txt_byteCnt.setValue("질의내용<br>(" + (contnByte) + "/2000 byte)");

    if(contnByte > standardByte){
        $c.win.alert( (contnByte - standardByte) + "바이트가 초과되었습니다. 초과된 내용은 자동삭제됩니다.\n");
        const contnValue = _obj.getValue();

        // 초과한 문자열을 삭제
        _obj.setValue(scwin.calcContn(contnValue, standardByte));

        // 바이트수를 재계산
        scwin.checkByte(_obj);
    }
};

/**
 * @method
 * @name getByte
 * @description 입력 컴포넌트 값의 바이트 수를 구한다(한글·줄바꿈 2byte).
 * @param {Object} _obj 대상 입력 컴포넌트
 * @returns {Number} 바이트 수
 * @hidden N
 */
scwin.getByte = function (_obj) {
    const sTmpCntnt = new String(_obj.getValue());	// 내용 저장 변수

    let iCounts = 0;	// 바이트 수 저장 변수

    for (let i = 0 ;i < sTmpCntnt.length; i++) {
        //  16 진수 변환
        const escapeChar = escape(sTmpCntnt.charAt(i))

        if (escapeChar === '%0A') {	// enter 처리
            iCounts += 2;
        } else if (escapeChar.length > 4) {	// 한글 2byte 처리
            iCounts += 2;
        } else  {
            iCounts++;
        }
    }
    return iCounts;
};

/**
 * @method
 * @name calcContn
 * @description 내용을 최대 바이트 이내로 잘라 반환한다(한글·줄바꿈 2byte).
 * @param {String} _contn 내용 문자열
 * @param {Number} _maximum 최대 바이트 수
 * @returns {String} 잘라낸 내용
 * @hidden N
 */
scwin.calcContn = function (_contn, _maximum) {
    let rContn = "";
    let nbytes = 0;	// 총 byte 수

    for (let i=0; i<_contn.length; i++) {
        const ch = _contn.charAt(i);

        let inc = 0;	// 증가치 변수

        if (escape(ch) === '%0A') {
            inc = 2;
        }else if (escape(ch).length > 4) {
            inc = 2;
        } else {
            inc = 1;
        }

        nbytes += inc;

        if (nbytes > _maximum) {	// _maximum 넘어서면 break
            break;
        }

        rContn += ch;	// ch 추가
    }

    return rContn;
};

/**
 * @method
 * @name fileTypeChk
 * @description 첨부파일 확장자가 허용 목록에 있는지 검사한다.
 * @param {String|Number} val 값
 * @returns {Number} 허용 확장자면 1, 아니면 0
 * @hidden N
 */
scwin.fileTypeChk = function(val) {

        // 파일 확장자 체크
        let isFileType = new Array("drt", "bmp", "gif", "jpeg", "jpg", "png",
				"hwp", "docx", "doc", "xls", "xlsx", "ppt", "pptx", "pdf",
				"zip", "txt");

        let fileType = val.substring(val.lastIndexOf(".") + 1).toLowerCase();

        let returnVal = 0;
        let typeChkCnt = 0;
        for (let i = 0; i < isFileType.length; i++) {
            if (isFileType[i] === fileType) {

                typeChkCnt++;
            }
        }

        if (typeChkCnt === 0) {

            returnVal = 1;
        }

        return returnVal;
    }

/**
 * @method
 * @name fileDown
 * @description 파일다운로드
 * @param {String} bzProcsNo 식별자
 * @param {Number} cmitContnSeq 일련번호
 * @param {String} cmitContnAttachFileTpCd 구분 코드
 * @param {String} cmitFileNm 명칭
 * @returns {void}
 * @hidden N
 */
scwin.fileDown = function(bzProcsNo, cmitContnSeq,cmitContnAttachFileTpCd, cmitFileNm) {

    dma_fileDownReq.set("cmitBzProcsNo",bzProcsNo);
    dma_fileDownReq.set("seq",cmitContnSeq);
    dma_fileDownReq.set("cmitContnAttachFileTpCd",cmitContnAttachFileTpCd);
    dma_fileDownReq.set("cmitAttachFileNm",cmitFileNm);

// if(cmitContnAttachFileTpCd == "10"){
//     $("#cmitAttachFileNm").val($("#cmitNm"+index).val());
// }else{
//     $("#cmitAttachFileNm").val($("#comNm"+index).val());
// }

    const url = "/api/listing/listinvstg/commitments/file-download";
    const param = {
        cmitBzProcsNo : bzProcsNo,
        seq : cmitContnSeq,
        cmitContnAttachFileTpCd : cmitContnAttachFileTpCd,
        cmitAttachFileNm : cmitFileNm
    };
    $c.data.downFile(url, "", param);
};

/**
 * @method
 * @name comFile
 * @description 이행증빙자료 컬럼 커스텀 포매터 — 상태에 따라 다운로드 링크·삭제·추가 아이콘 HTML 을 만든다.
 * @param {*} data 셀 값(원본 데이터)
 * @param {String} formattedData 표시 형식 문자열
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} colIndex 열 인덱스
 * @returns {String} 셀에 표시할 HTML
 * @hidden N
 */
scwin.comFile = function(data, formattedData, rowIndex, colIndex) {
    let rowData = dlt_commitmentsRes2.getRowJSON(rowIndex);
    let statCd = rowData.cmitPerfmStatCd||'';
    let fileNm     = rowData.comFileNm||'';
    let bzProcsNo  = rowData.bzProcsNo||'';
    let cmitContnSeq = rowData.cmitContnSeq||'';

    let isEditable = (statCd === '' || statCd ==='20' );

    // 현업최초등록 또는 반려시 (수정가능)
    if(isEditable) {
        if (fileNm !== '') {
        // 파일이 존재할 떄 : 삭제 아이콘 + 다운로드 링크
        return '<div title="'+fileNm+'">' +
               ' <img src="/websquare/_websquare_/externalJS/ckfinder/skins/kama/images/toolbar/delete.gif" style="cursor:pointer" onclick="fn_fileDel(\'' +  fileNm + '\', ' + rowIndex + ')"/>' +
               ' <a href="javascript:fn_FileDown(\'' + bzProcsNo + '\', \'' + cmitContnSeq +  '\', \'0\', ' + rowIndex +')">' +
               '   <img src="/cm/images/dis/attach_5.gif" border="0"  /> '+ fileNm +
               ' </a> ' +
               '</div>';
        }  else {
        // 파일이 없을떄 : 파일선택 버튼  websquare/_websquare_/uiplugin/grid/images/plus.gif
        return '<div style="display:inline-flex; align-items:center "cursor:pointer;">' +
                '<img src="/websquare/_websquare_/uiplugin/grid/images/plus.gif" style="cursor:pointer; vertical-align:middle; margin-right:6px;" onclick="fn_changeFile('+ rowIndex + ')">' +
                '<span style="color:#666;" id="fileName_' + rowIndex +'">선택된 파일이 없습니다</span>' +
                '</div>';
        }
    // 읽기전용
    } else {
        if (fileNm !== '') {
        // 파일이 존재할 떄 : 다운로드 링크만
            return '<div title="'+fileNm+'">' +
               ' <a href="javascript:scwin.fileDown(\'' + bzProcsNo + '\', \'' + cmitContnSeq +  '\', \'0\', ' + rowIndex +')">' +
               '   <img src="/cm/images/dis/attach_5.gif" border="0"  /> '+ fileNm +
               ' </a> ' +
               '</div>';
        } else {
        // 파일이 없을 떄 :
            return '-';
        }

    }
}

/**
 * @method
 * @name opin
 * @description 조치내용/의견 컬럼 커스텀 포매터 — 수정 가능 상태면 textarea, 아니면 텍스트로 표시한다.
 * @param {*} data 셀 값(원본 데이터)
 * @param {String} formmatedData 표시 형식 문자열
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} colIndex 열 인덱스
 * @returns {String} 셀에 표시할 HTML
 * @hidden N
 */
scwin.opin = function(data, formmatedData, rowIndex, colIndex ) {

    let rowData     = dlt_commitmentsRes2.getRowJSON(rowIndex);
    let statCd      = rowData.cmitPerfmStatCd||'';
    let opinText    = rowData.perfmOpinContn||'';

    if(statCd === '' || statCd === '20' ){
    // Textarea영역
        return '<textarea maxlength= "200" style="heigth:50px; width:100% resize:vertical;"' +
             'onchange="scwin.fn_chageOpin(' +rowIndex + ',this.value)">' + opinText + '</textarea>';
    } else {
        // Text
        return '<span>' + opinText + '</span>';

    }

}
